/* Counts up to a target value once it scrolls into view */
function AnimatedCounter({ value, suffix = '', duration = 1400 }) {
  const [ref, visible] = useReveal();
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    if (!visible) return;
    let start = null;
    let frame;
    const step = (ts) => {
      if (start === null) start = ts;
      const progress = Math.min(1, (ts - start) / duration);
      setDisplay(Math.floor(progress * value));
      if (progress < 1) frame = requestAnimationFrame(step);
      else setDisplay(value);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [visible, value, duration]);

  return (
    <span ref={ref} className="font-display text-4xl font-semibold gradient-gold-text">
      {display}{suffix}
    </span>
  );
}

/* Shared click-ripple effect for premium buttons — imperative DOM, no re-render needed */
function addRipple(e) {
  const button = e.currentTarget;
  const rect = button.getBoundingClientRect();
  const size = Math.max(rect.width, rect.height);
  const x = (e.clientX || rect.left + rect.width / 2) - rect.left - size / 2;
  const y = (e.clientY || rect.top + rect.height / 2) - rect.top - size / 2;
  const ripple = document.createElement('span');
  ripple.className = 'btn-ripple';
  ripple.style.width = ripple.style.height = `${size}px`;
  ripple.style.left = `${x}px`;
  ripple.style.top = `${y}px`;
  button.appendChild(ripple);
  setTimeout(() => ripple.remove(), 650);
}

