function generateId(prefix) { return `${prefix}_${Date.now()}_${Math.floor(Math.random() * 1000)}`; }
function generateISRC() {
  const yy = new Date().getFullYear().toString().slice(-2);
  const rand = Math.floor(10000 + Math.random() * 89999);
  return `IN-S2X-${yy}-${rand}`;
}
function generateUPC() { return Array.from({ length: 12 }, () => Math.floor(Math.random() * 10)).join(''); }
function formatRelative(ts) {
  if (!ts) return 'Never';
  const diff = Date.now() - ts;
  if (diff < 60000) return 'Just now';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
  return `${Math.floor(diff / 86400000)}d ago`;
}
function isOnline(ts) { return ts && Date.now() - ts < ACTIVE_WINDOW_MS; }

/* ---- Real password hashing (SHA-256 via the browser's Web Crypto API). ----
   This is genuine cryptographic hashing, not obfuscation \u2014 a stored hash
   cannot practically be reversed back into the password. What it does NOT
   do: replace server-side auth. Anyone using this app's own browser console
   can still call the same JS functions directly and bypass the UI entirely,
   because there is no server deciding what is/isn't allowed \u2014 that requires
   a real backend. Hashing here protects the *stored* password value, not the
   login flow itself. */
async function hashPassword(plain) {
  try {
    const enc = new TextEncoder().encode(plain);
    const buf = await crypto.subtle.digest('SHA-256', enc);
    return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
  } catch (e) {
    return null; // Web Crypto unavailable (e.g. non-HTTPS context)
  }
}
function generateSecurePassword() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
  let out = '';
  for (let i = 0; i < 12; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}
function isUsernameTaken(username, clients, excludeId) {
  const norm = username.trim().toLowerCase();
  return clients.some((c) => c.id !== excludeId && c.username && c.username.toLowerCase() === norm);
}
function normalizeUsername(name) {
  return name.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
}
function formatDDMMYYYY(iso) {
  if (!iso) return '\u2014\u2014 / \u2014\u2014 / \u2014\u2014\u2014\u2014';
  const parts = iso.split('-');
  if (parts.length !== 3) return iso;
  const [y, m, d] = parts;
  return `${d} / ${m} / ${y}`;
}
function nextCertificateNumber(clients) {
  const used = clients.reduce((sum, c) => sum + c.releases.filter((r) => r.certificateId).length, 0);
  return used + 1;
}
function formatCertificateId(n) {
  return `SW-2026-${String(n).padStart(6, '0')}`;
}

