/* Shown exactly once, right after a password is generated (new account or
   reset). The password is never shown again after this \u2014 only its hash is
   kept \u2014 so whoever is looking at this screen needs to save or relay it now. */
function PasswordRevealModal({ data, onClose }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try { await navigator.clipboard.writeText(data.password); setCopied(true); setTimeout(() => setCopied(false), 1800); } catch (e) {}
  };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-6 fade-in" style={{ background: 'rgba(0,0,0,0.8)' }}>
      <div className="glass rounded-2xl p-7 w-full" style={{ maxWidth: 380 }}>
        <ShieldCheck size={26} className="text-gold mb-4" />
        <p className="font-display text-base font-medium">Save this password now</p>
        <p className="text-gray-400 text-sm mt-1.5">It will not be shown again. Only a secure hash of it is stored.</p>
        <div className="mt-5 space-y-3">
          <div>
            <p className="text-gray-500" style={{ fontSize: 11 }}>Username</p>
            <p className="font-mono text-sm">{data.username}</p>
          </div>
          <div>
            <p className="text-gray-500" style={{ fontSize: 11 }}>Password</p>
            <div className="flex items-center gap-2">
              <p className="font-mono text-gold text-lg">{data.password}</p>
              <button onPointerDown={copy} aria-label="Copy password" className="text-gray-400 hover:text-gold transition-colors">
                {copied ? <Check size={15} /> : <Copy size={15} />}
              </button>
            </div>
          </div>
        </div>
        <button onPointerDown={onClose} className="mt-6 w-full gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full hover:brightness-110 transition-all">
          {copied ? 'Copied \u2014 Done' : "I've Saved It"}
        </button>
      </div>
    </div>
  );
}

