function ArtistLogin({ clients, onBack, onPickSignup, onSuccess }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [show, setShow] = useState(false);
  const [error, setError] = useState('');
  const [checking, setChecking] = useState(false);

 const submit = async () => {
    if (!username.trim() || !password.trim()) {
      setError('Please enter both your email and password.');
      return;
    }

    setChecking(true);
    setError('');

    try {
      // Look up the artist inside the Supabase table by their email
      const { data, error } = await supabase
        .from('artists')
        .select('*')
        .eq('email', username.trim())
        .maybeSingle();

      if (error) {
        setError(error.message);
        setChecking(false);
        return;
      

      if (!data) {
        setError('No account found with that email address.');
        setChecking(false);
        return;
      }

      // Verify the password matching the text in the DB column
      if (data.password !== password) {
        setError('Incorrect password.');
        setChecking(false);
        return;
      }

      setChecking(false);
      onSuccess(data);
    }
    } catch (err) {
      setError('Something went wrong connecting to the database.');
      setChecking(false);
    }
  };

      if (!data) {
        setError('No account found with that email address.');
        setChecking(false);
        return;
      }

      // Verify the password matching the text in the DB column
      if (data.password !== password) {
        setError('Incorrect password.');
        setChecking(false);
        return;
      }

      setChecking(false);
    onSuccess(data);
    ;
  
    return (
    <div className="min-h-screen flex items-center justify-center px-6 fade-in">
      <div className="w-full max-w-sm">
        <Brand sub="Artist Sign In" />
        <div className="glass rounded-2xl p-7 mt-8 space-y-4">
          <label className="block">
            <span className="text-xs text-gray-400">Username</span>
            <input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="Your login username"
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600 font-mono" />
          </label>
          <label className="block">
            <span className="text-xs text-gray-400">Password</span>
            <div className="mt-1.5 flex items-center border border-gold-15 rounded-xl px-4 focus-within:border-gold-30">
              <input
                type={show ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && submit()}
                placeholder="Your password"
                className="flex-1 bg-transparent py-2.5 text-sm outline-none placeholder:text-gray-600"
              />
              <button type="button" onPointerDown={() => setShow((s) => !s)} className="text-gray-500 hover:text-gold transition-colors">
                {show ? <EyeOff size={15} /> : <Eye size={15} />}
              </button>
            </div>
          </label>
          {error && (
            <p className="text-xs flex items-center gap-1.5" style={{ color: '#E08585' }}>
              <AlertCircle size={13} /> {error}
            </p>
          )}
          <button onPointerDown={submit} disabled={checking} className="w-full gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full hover:brightness-110 transition-all disabled:opacity-60">
            {checking ? 'Checking\u2026' : 'Sign In'}
          </button>
          <p className="text-gray-500 text-center" style={{ fontSize: 11 }}>
            New here?{' '}
            <button onPointerDown={onPickSignup} className="text-gold hover:brightness-110">Create your account</button>
            {' '}&middot;{' '}
            <a href={PORTAL_WHATSAPP_LINK} target="_blank" rel="noopener noreferrer" className="text-gold">Forgot password? Message us</a>
          </p>
        </div>
        <button onPointerDown={onBack} className="mt-5 text-gray-500 text-sm inline-flex items-center gap-1 hover:text-gold transition-colors">
          <ChevronLeft size={14} /> Back
        </button>
      </div>
    </div>
  );
}

/* Self-serve sign-up. IMPORTANT: this simulates what a "Continue with Google"
   flow would look like — it is NOT connected to a real Google account. Real
   Google Sign-In needs a Google Cloud OAuth Client ID tied to a domain you
   control, plus a backend to verify the returned token. Neither exists here,
   so this collects a name/email directly and creates the account the same
   way a verified Google sign-in eventually would. */
function ArtistSignup({ clients, onBack, onCreate }) {
  const [name, setName] = useState('');
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  const submit = async () => {
    if (!name.trim() || !email.trim() || !password.trim()) {
      setError('Name, email, and password are required.');
      return;
    }
    if (!email.includes('@')) {
      setError('Enter a valid email address.');
      return;
    }

    setError('');
    
    try {
      // Insert the new artist into the Supabase database
      const { data, error } = await supabase
        .from('artists')
        .insert([
          { 
            name: name.trim(), 
            email: email.trim().toLowerCase(), 
            password: password 
          }
        ])
        .select()
        .single();

      if (error) {
        setError(error.message);
        return;
      }

      // If successful, pass the data up to log them in automatically
      if (data) {
        onCreate(data);
      }
    } catch (err) {
      setError('Something went wrong connecting to the database.');
    }
  };


  return (
    <div className="min-h-screen flex items-center justify-center px-6 fade-in">
      <div className="w-full max-w-sm">
        <Brand sub="Create Your Account" />
        <div className="glass rounded-2xl p-7 mt-8 space-y-4">
          <div className="glass rounded-xl p-3.5 flex items-start gap-2.5" style={{ borderColor: 'rgba(200,166,70,0.3)' }}>
            <AlertCircle size={14} className="text-gold shrink-0 mt-0.5" />
            <p className="text-gray-400" style={{ fontSize: 11 }}>
              Demo sign-up. This preview isn&rsquo;t connected to a real Google account yet.
            </p>
          </div>
          <button
            type="button"
            className="w-full glass rounded-xl px-4 py-3 flex items-center justify-center gap-2.5 text-sm hover:border-gold-30 transition-all"
            onPointerDown={() => { if (!name.trim()) setName('Google User'); if (!email.trim()) setEmail('artist@gmail.com'); }}
          >
            <LogIn size={16} className="text-gold" /> Continue with Google (Demo)
          </button>
          <div className="flex items-center gap-3">
            <div className="flex-1 h-px" style={{ background: 'rgba(200,166,70,0.16)' }} />
            <span className="text-gray-600" style={{ fontSize: 11 }}>or enter manually</span>
            <div className="flex-1 h-px" style={{ background: 'rgba(200,166,70,0.16)' }} />
          </div>
          <label className="block">
            <span className="text-xs text-gray-400">Artist / Band Name</span>
            <input
              value={name}
              onChange={(e) => { setName(e.target.value); if (!username) setUsername(normalizeUsername(e.target.value)); }}
              placeholder="Your artist name"
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600"
            />
          </label>
          <label className="block">
            <span className="text-xs text-gray-400">Username</span>
            <input value={username} onChange={(e) => setUsername(normalizeUsername(e.target.value))} placeholder="unique login handle"
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600 font-mono" />
          </label>
          <label className="block">
            <span className="text-xs text-gray-400">Email</span>
            <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@gmail.com" type="email"
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600" />
          </label>
          {error && (
            <p className="text-xs flex items-center gap-1.5" style={{ color: '#E08585' }}>
              <AlertCircle size={13} /> {error}
            </p>
          )}
          <p className="text-gray-500" style={{ fontSize: 11 }}>A secure password is generated automatically and shown once on the next screen.</p>
          <button onPointerDown={submit} className="w-full gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full hover:brightness-110 transition-all">
            Create Account
          </button>
        </div>
        <button onPointerDown={onBack} className="mt-5 text-gray-500 text-sm inline-flex items-center gap-1 hover:text-gold transition-colors">
          <ChevronLeft size={14} /> Back
        </button>
      </div>
    </div>
  );
}

