/* Account panel: change password (re-hashes and overwrites the stored hash;
   the old plaintext/hash is never recoverable once replaced) and a quick
   link to support. */
function AccountModal({ client, onPasswordChanged, onClose }) {
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    if (next.length < 6) { setError('New password must be at least 6 characters.'); return; }
    if (next !== confirm) { setError('New passwords do not match.'); return; }
    setBusy(true);
    const currentHash = await hashPassword(current);
    if (currentHash !== client.passwordHash) {
      setBusy(false);
      setError('Current password is incorrect.');
      return;
    }
    const newHash = await hashPassword(next);
    await onPasswordChanged(newHash);
    setSuccess(true);
    setError('');
    setBusy(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-6 fade-in" style={{ background: 'rgba(0,0,0,0.8)' }}>
      <div className="glass rounded-2xl p-7 w-full" style={{ maxWidth: 380 }}>
        <div className="flex items-center justify-between mb-5">
          <p className="font-display text-base font-medium">Account</p>
          <button onPointerDown={onClose} aria-label="Close" className="text-gray-400 hover:text-gold transition-colors"><X size={18} /></button>
        </div>
        <p className="text-gray-500" style={{ fontSize: 11 }}>Username</p>
        <p className="font-mono text-sm mb-5">{client.username}</p>

        {success ? (
          <p className="text-sm flex items-center gap-2" style={{ color: '#7DD3A0' }}><Check size={15} /> Password updated.</p>
        ) : (
          <div className="space-y-3">
            <label className="block">
              <span className="text-xs text-gray-400">Current Password</span>
              <input type="password" value={current} onChange={(e) => setCurrent(e.target.value)}
                className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30" />
            </label>
            <label className="block">
              <span className="text-xs text-gray-400">New Password</span>
              <input type="password" value={next} onChange={(e) => setNext(e.target.value)}
                className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30" />
            </label>
            <label className="block">
              <span className="text-xs text-gray-400">Confirm New Password</span>
              <input type="password" value={confirm} onChange={(e) => setConfirm(e.target.value)}
                className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30" />
            </label>
            {error && <p className="text-xs flex items-center gap-1.5" style={{ color: '#E08585' }}><AlertCircle size={13} /> {error}</p>}
            <button onPointerDown={submit} disabled={busy} className="w-full gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full hover:brightness-110 transition-all disabled:opacity-60">
              {busy ? 'Saving\u2026' : 'Update Password'}
            </button>
          </div>
        )}

        <a href={PORTAL_WHATSAPP_LINK} target="_blank" rel="noopener noreferrer" className="mt-5 flex items-center justify-center gap-1.5 text-gold text-sm hover:brightness-110">
          <MessageCircle size={14} /> Contact Support
        </a>
      </div>
    </div>
  );
}

