function AdminClientDetail({ client, certBase, onSave, onDelete, onBack, onResetPassword }) {
  const [draft, setDraft] = useState(client);
  useEffect(() => { setDraft(client); }, [client.id]);
  const certCounterRef = useRef(certBase);
  const [resetting, setResetting] = useState(false);

  const doReset = async () => {
    setResetting(true);
    await onResetPassword(client);
    setResetting(false);
  };

  const updateField = (key, value) => setDraft((d) => ({ ...d, [key]: value }));
  const updateRelease = (id, patch) => setDraft((d) => ({
    ...d,
    releases: d.releases.map((r) => {
      if (r.id !== id) return r;
      const next = { ...r, ...patch };
      // A certificate is minted the first time a release becomes Live or Scheduled.
      // The ID is generated once and then permanent — it is never reassigned or reused.
      if (!next.certificateId && (next.status === 'live' || next.status === 'scheduled')) {
        certCounterRef.current += 1;
        next.certificateId = formatCertificateId(certCounterRef.current);
      }
      return next;
    }),
  }));
  const removeRelease = (id) => setDraft((d) => ({ ...d, releases: d.releases.filter((r) => r.id !== id) }));
  const addRelease = () => setDraft((d) => ({
    ...d,
    releases: [...d.releases, { id: generateId('r'), title: 'New Release', type: 'Single', status: 'in_review', releaseDate: '', isrc: generateISRC(), upc: generateUPC(), certificateId: null }],
  }));

  return (
    <div className="fade-in">
      <button onPointerDown={onBack} className="text-gray-400 hover:text-gold text-sm inline-flex items-center gap-1 mb-6 transition-colors">
        <ChevronLeft size={14} /> All Clients
      </button>

      <div className="glass rounded-2xl p-6 mb-6">
        <div className="grid sm:grid-cols-2 gap-5">
          <label className="block">
            <span className="text-xs text-gray-400">Artist / Band Name</span>
            <input value={draft.name} onChange={(e) => updateField('name', e.target.value)}
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30" />
          </label>
          <label className="block">
            <span className="text-xs text-gray-400">Username</span>
            <input value={draft.username || ''} onChange={(e) => updateField('username', normalizeUsername(e.target.value))}
              className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 font-mono" />
          </label>
        </div>
        <button
          type="button"
          onPointerDown={doReset}
          disabled={resetting}
          className="mt-4 glass px-4 py-2 rounded-xl text-xs inline-flex items-center gap-2 hover:border-gold-30 transition-all disabled:opacity-60"
        >
          <KeyRound size={13} className="text-gold" /> {resetting ? 'Generating\u2026' : 'Reset Password'}
        </button>
        <label className="block mt-5">
          <span className="text-xs text-gray-400">Email (optional)</span>
          <input value={draft.email || ''} onChange={(e) => updateField('email', e.target.value)} placeholder="artist@gmail.com"
            className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600" />
        </label>
        <p className="text-gray-500 mt-3" style={{ fontSize: 11 }}>
          Last active: {formatRelative(client.lastActive)} {isOnline(client.lastActive) && <span className="text-gold">&middot; Online now</span>}
        </p>
      </div>

      <div className="flex items-center justify-between mb-3">
        <p className="font-display text-sm font-medium">Releases</p>
        <button onPointerDown={addRelease} className="text-gold text-xs font-display inline-flex items-center gap-1 hover:brightness-110">
          <Plus size={13} /> Add Release
        </button>
      </div>

      <div className="space-y-3">
        {draft.releases.length === 0 && <p className="text-gray-500 text-sm">No releases yet. Add one above.</p>}
        {draft.releases.map((r) => (
          <div key={r.id} className="glass rounded-2xl p-5">
            <div className="grid sm:grid-cols-2 gap-3">
              <label className="block">
                <span className="text-gray-500" style={{ fontSize: 11 }}>Title</span>
                <input value={r.title} onChange={(e) => updateRelease(r.id, { title: e.target.value })}
                  className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30" />
              </label>
              <div className="grid grid-cols-2 gap-3">
                <label className="block">
                  <span className="text-gray-500" style={{ fontSize: 11 }}>Type</span>
                  <select value={r.type} onChange={(e) => updateRelease(r.id, { type: e.target.value })} style={{ colorScheme: 'dark' }}
                    className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30">
                    {RELEASE_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
                  </select>
                </label>
                <label className="block">
                  <span className="text-gray-500" style={{ fontSize: 11 }}>Status</span>
                  <select value={r.status} onChange={(e) => updateRelease(r.id, { status: e.target.value })} style={{ colorScheme: 'dark' }}
                    className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30">
                    {Object.keys(STATUS_META).map((s) => <option key={s} value={s}>{STATUS_META[s].label}</option>)}
                  </select>
                </label>
              </div>
              <label className="block">
                <span className="text-gray-500" style={{ fontSize: 11 }}>Release Date</span>
                <input type="date" value={r.releaseDate} onChange={(e) => updateRelease(r.id, { releaseDate: e.target.value })} style={{ colorScheme: 'dark' }}
                  className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30 text-gray-300" />
              </label>
              <div className="grid grid-cols-2 gap-3">
                <label className="block">
                  <span className="text-gray-500" style={{ fontSize: 11 }}>ISRC</span>
                  <input value={r.isrc} onChange={(e) => updateRelease(r.id, { isrc: e.target.value })}
                    className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30 font-mono" style={{ fontSize: 12 }} />
                </label>
                <label className="block">
                  <span className="text-gray-500" style={{ fontSize: 11 }}>UPC</span>
                  <input value={r.upc} onChange={(e) => updateRelease(r.id, { upc: e.target.value })}
                    className="mt-1 w-full bg-transparent border border-gold-15 rounded-lg px-3 py-2 text-sm outline-none focus:border-gold-30 font-mono" style={{ fontSize: 12 }} />
                </label>
              </div>
            </div>
            <div className="flex items-center justify-between mt-3">
              <p className="text-gray-500" style={{ fontSize: 11 }}>
                Certificate:{' '}
                {r.certificateId ? (
                  <span className="font-mono text-gold">{r.certificateId}</span>
                ) : (
                  <span>Issued automatically once Live or Scheduled</span>
                )}
              </p>
              <button onPointerDown={() => removeRelease(r.id)} className="text-xs inline-flex items-center gap-1.5 hover:brightness-110" style={{ color: '#E08585' }}>
                <Trash2 size={13} /> Remove Release
              </button>
            </div>
          </div>
        ))}
      </div>

      <div className="flex items-center gap-3 mt-6">
        <button onPointerDown={() => onSave(draft)} className="gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full inline-flex items-center gap-2 hover:brightness-110 transition-all">
          <Save size={15} /> Save Changes
        </button>
        <button onPointerDown={() => onDelete(client.id)} className="glass px-5 py-2.5 rounded-full text-sm inline-flex items-center gap-2 hover:border-gold-30 transition-all" style={{ color: '#E08585' }}>
          <Trash2 size={15} /> Delete Client
        </button>
      </div>
    </div>
  );
}

function AdminDashboard({ clients, onSaveClient, onDeleteClient, onAddClient, onResetPassword, onRefresh, onLogout }) {
  const [query, setQuery] = useState('');
  const [selectedId, setSelectedId] = useState(null);
  const [showAdd, setShowAdd] = useState(false);
  const [newName, setNewName] = useState('');
  const [newUsername, setNewUsername] = useState('');
  const [addError, setAddError] = useState('');
  const [revealPassword, setRevealPassword] = useState(null); // { username, password } shown once

  const selected = clients.find((c) => c.id === selectedId);
  const filtered = clients.filter((c) => c.name.toLowerCase().includes(query.toLowerCase()));
  const onlineCount = clients.filter((c) => isOnline(c.lastActive)).length;
  const totalReleases = clients.reduce((s, c) => s + c.releases.length, 0);
  const certBase = nextCertificateNumber(clients) - 1;

  const submitAdd = async () => {
    const uname = normalizeUsername(newUsername || newName);
    if (!newName.trim() || !uname) { setAddError('Name and username are required.'); return; }
    if (isUsernameTaken(uname, clients)) { setAddError('That username is already taken.'); return; }
    setAddError('');
    const password = generateSecurePassword();
    const passwordHash = await hashPassword(password);
    const newClient = {
      id: generateId('c'), username: uname, name: newName.trim(), passwordHash,
      createdAt: new Date().toISOString().slice(0, 10), lastActive: null, releases: [],
    };
    onAddClient(newClient);
    setRevealPassword({ username: uname, password });
    setNewName(''); setNewUsername(''); setShowAdd(false);
  };

  const handleResetPassword = async (client) => {
    const password = generateSecurePassword();
    const passwordHash = await hashPassword(password);
    onResetPassword(client.id, passwordHash);
    setRevealPassword({ username: client.username, password });
  };

  if (selected) {
    return (
      <div className="max-w-3xl mx-auto px-5 md:px-8 py-10">
        <AdminClientDetail
          client={selected}
          certBase={certBase}
          onBack={() => setSelectedId(null)}
          onSave={(draft) => { onSaveClient(draft); setSelectedId(null); }}
          onDelete={(id) => { onDeleteClient(id); setSelectedId(null); }}
          onResetPassword={handleResetPassword}
        />
        {revealPassword && <PasswordRevealModal data={revealPassword} onClose={() => setRevealPassword(null)} />}
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-5 md:px-8 py-10 fade-in">
      <div className="flex flex-wrap items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="font-display text-2xl md:text-3xl font-semibold">Team Access</h1>
          <p className="text-gray-400 text-sm mt-1">Manage every client from one place.</p>
        </div>
        <div className="flex items-center gap-2">
          <button onPointerDown={onRefresh} className="glass p-2.5 rounded-full hover:border-gold-30 transition-all" aria-label="Refresh"><RefreshCw size={15} className="text-gold" /></button>
          <button onPointerDown={onLogout} className="text-gray-400 hover:text-gold text-sm inline-flex items-center gap-1.5 transition-colors"><LogOut size={15} /> Lock</button>
        </div>
      </div>

      <div className="grid sm:grid-cols-3 gap-4 mb-6">
        <div className="glass rounded-2xl p-5">
          <Users size={17} className="text-gold mb-2" />
          <p className="font-display text-2xl font-semibold">{clients.length}</p>
          <p className="text-gray-400 text-xs mt-1">Total Clients</p>
        </div>
        <div className="glass rounded-2xl p-5">
          <Disc3 size={17} className="text-gold mb-2" />
          <p className="font-display text-2xl font-semibold">{totalReleases}</p>
          <p className="text-gray-400 text-xs mt-1">Total Releases</p>
        </div>
        <div className="glass rounded-2xl p-5">
          <Radio size={17} className="mb-2" style={{ color: onlineCount > 0 ? '#7DD3A0' : '#6B7280' }} />
          <p className="font-display text-2xl font-semibold flex items-center gap-2">
            {onlineCount}
            {onlineCount > 0 && <span className="rounded-full pulse-dot" style={{ width: 8, height: 8, background: '#7DD3A0' }} />}
          </p>
          <p className="text-gray-400 text-xs mt-1">Online Now</p>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 mb-4">
        <div className="glass rounded-full px-4 py-2 flex items-center gap-2 flex-1" style={{ minWidth: 200 }}>
          <Search size={15} className="text-gray-500 shrink-0" />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search clients"
            className="bg-transparent outline-none text-sm w-full placeholder:text-gray-500" />
        </div>
        <button onPointerDown={() => setShowAdd((s) => !s)} className="gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full inline-flex items-center gap-2 hover:brightness-110 transition-all">
          <Plus size={15} /> Add Client
        </button>
      </div>

      {showAdd && (
        <div className="glass rounded-2xl p-5 mb-4 fade-in space-y-3">
          <div className="flex flex-wrap items-end gap-3">
            <label className="block flex-1" style={{ minWidth: 180 }}>
              <span className="text-xs text-gray-400">Artist / Band Name</span>
              <input
                value={newName}
                onChange={(e) => { setNewName(e.target.value); if (!newUsername) setNewUsername(normalizeUsername(e.target.value)); }}
                placeholder="e.g. Ananya Kapoor"
                className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600"
              />
            </label>
            <label className="block flex-1" style={{ minWidth: 180 }}>
              <span className="text-xs text-gray-400">Username</span>
              <input
                value={newUsername}
                onChange={(e) => setNewUsername(normalizeUsername(e.target.value))}
                placeholder="unique login handle"
                className="mt-1.5 w-full bg-transparent border border-gold-15 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-gold-30 placeholder:text-gray-600 font-mono"
              />
            </label>
            <button onPointerDown={submitAdd} className="gradient-gold-bg text-black font-display font-semibold text-sm px-5 py-2.5 rounded-full hover:brightness-110 transition-all">
              Create Account
            </button>
          </div>
          <p className="text-gray-500" style={{ fontSize: 11 }}>A secure password is generated automatically and shown once after you create the account.</p>
          {addError && (
            <p className="text-xs flex items-center gap-1.5" style={{ color: '#E08585' }}>
              <AlertCircle size={13} /> {addError}
            </p>
          )}
        </div>
      )}

      {revealPassword && <PasswordRevealModal data={revealPassword} onClose={() => setRevealPassword(null)} />}

      <div className="glass rounded-2xl overflow-x-auto">
        <table className="w-full text-sm" style={{ minWidth: 560 }}>
          <thead>
            <tr className="border-b border-gold-15 text-left text-gray-500">
              <th className="font-display font-medium px-5 py-3.5" style={{ fontSize: 12 }}>Client</th>
              <th className="font-display font-medium px-5 py-3.5" style={{ fontSize: 12 }}>Username</th>
              <th className="font-display font-medium px-5 py-3.5" style={{ fontSize: 12 }}>Releases</th>
              <th className="font-display font-medium px-5 py-3.5" style={{ fontSize: 12 }}>Activity</th>
              <th className="font-display font-medium px-5 py-3.5" style={{ fontSize: 12 }}></th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((c) => (
              <tr key={c.id} className="border-b border-gold-15 hover:bg-white/[0.02] transition-colors">
                <td className="px-5 py-3.5">
                  <div className="flex items-center gap-3">
                    <span className="w-8 h-8 rounded-full gradient-gold-bg flex items-center justify-center font-display text-black text-xs font-semibold shrink-0">{c.name.charAt(0)}</span>
                    <div className="min-w-0">
                      <p className="truncate">{c.name}</p>
                      {c.email && <p className="text-gray-500 truncate" style={{ fontSize: 11 }}>{c.email}</p>}
                    </div>
                  </div>
                </td>
                <td className="px-5 py-3.5 text-gray-400 font-mono" style={{ fontSize: 12 }}>{c.username}</td>
                <td className="px-5 py-3.5 text-gray-400">{c.releases.length}</td>
                <td className="px-5 py-3.5">
                  {isOnline(c.lastActive) ? (
                    <span className="inline-flex items-center gap-1.5 text-xs" style={{ color: '#7DD3A0' }}>
                      <span className="rounded-full pulse-dot" style={{ width: 6, height: 6, background: '#7DD3A0' }} /> Online now
                    </span>
                  ) : (
                    <span className="text-gray-500 text-xs">{formatRelative(c.lastActive)}</span>
                  )}
                </td>
                <td className="px-5 py-3.5 text-right">
                  <button onPointerDown={() => setSelectedId(c.id)} className="text-gold text-xs font-display inline-flex items-center gap-1 hover:brightness-110">
                    Manage <ChevronRight size={13} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

